// Resilience4j：重试 + 熔断 + 降级（示意）
@Service
public class LlmService {
    private final ChatClient primary, backup;
    LlmService(@Qualifier("primary") ChatClient p, @Qualifier("backup") ChatClient b) { primary = p; backup = b; }

    @CircuitBreaker(name = "llm-primary", fallbackMethod = "fallback")
    @Retry(name = "llm-primary")
    public String ask(String q) {
        return primary.prompt().user(q).call().content();
    }

    private String fallback(String q, Throwable t) {
        try {
            return backup.prompt().user(q).call().content();      // 备用模型
        } catch (Exception e) {
            return "当前咨询人数较多，已为您转接人工客服。";          // 兜底
        }
    }
}
