// 伪网关路由
public CompletionResult route(ChatReq req) {
  ModelSpec m = policy.select(req.taskType(), req.tenant(), req.budget());
  try {
    return client.complete(m, req).timeout(m.timeout());
  } catch (TimeoutException | Provider5xx e) {
    ModelSpec fb = policy.fallback(m);
    metrics.failover(m, fb);
    return client.complete(fb, req);
  }
}
